<?php declare(strict_types=1);require __DIR__.'/bootstrap.php';$p=$_SESSION['portal_user']??null;if(!$p){header('Location:portal-login.php');exit;}?><!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="assets/app.css?v=10"><title><?=e($p['company_name'])?> portal</title></head><body><main class="page" style="max-width:980px;margin:auto"><div class="page-head"><div><h1><?=e($p['company_name'])?> support</h1><p><?=e($p['email'])?></p></div><div><button class="btn primary" id="new">＋ New ticket</button> <a class="btn" href="portal-logout.php">Sign out</a></div></div><div id="content"></div></main>
<script>const csrf=<?=json_encode(csrf_token())?>,root=document.querySelector('#content'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),api=async(a,o={})=>{o.headers={...(o.headers||{}),'X-CSRF-Token':csrf,'Content-Type':'application/json'};const r=await fetch('api/portal.php?action='+a,o),j=await r.json();if(!r.ok)throw Error(j.error);return j};async function list(){const j=await api('tickets');root.innerHTML='<section class="panel"><div class="table-wrap"><table><thead><tr><th>#</th><th>Subject</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody>'+j.items.map(x=>`<tr><td>${esc(x.ticket_no)}</td><td>${esc(x.subject)}</td><td>${esc(x.priority)}</td><td>${esc(x.status)}</td><td><button class="btn small" data-id="${x.id}">Open</button></td></tr>`).join('')+'</tbody></table></div></section>';root.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id))}async function detail(id){const j=await api('ticket&id='+id),x=j.ticket;root.innerHTML=`<button class="btn" id="back">← Tickets</button><section class="panel"><h2>${esc(x.subject)}</h2><p>${esc(x.description)}</p><small>${esc(x.status)} · ${esc(x.priority)}</small></section><section class="panel"><h3>Replies</h3>${j.replies.map(r=>`<div class="mini-row"><div><b>${r.portal_user_id?'You':esc(r.user_name||'Support')}</b><p>${esc(r.body)}</p></div><small>${esc(r.created_at)}</small></div>`).join('')}<form id="reply"><label class="field"><span>Reply</span><textarea name="body" required></textarea></label><button class="btn primary">Send</button></form></section>`;document.querySelector('#back').onclick=list;document.querySelector('#reply').onsubmit=async e=>{e.preventDefault();await api('reply',{method:'POST',body:JSON.stringify({ticket_id:+id,body:e.target.body.value})});detail(id)}}document.querySelector('#new').onclick=()=>{root.innerHTML=`<section class="panel"><h2>New ticket</h2><form id="create" class="form-grid"><label class="field full"><span>Subject</span><input name="subject" required></label><label class="field"><span>Priority</span><select name="priority"><option>low</option><option selected>medium</option><option>high</option><option>urgent</option></select></label><label class="field full"><span>Description</span><textarea name="description" required></textarea></label><button class="btn primary">Create</button></form></section>`;document.querySelector('#create').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const j=await api('create',{method:'POST',body:JSON.stringify(f)});detail(j.id)}};list();</script></body></html>
